#!/usr/bin/env node
// ============================================================
// patch-lotR3b-admin-ordre-bijoux.mjs  -  ZENORIA_GRID_ORDER_V3
//
// Lot R3b : réglage d'administration « Ordre des bijoux » (mode, fréquence, « Mélanger maintenant ») et lecture de ce
// réglage par la grille d'accueil. Le SQL (lot R3a : clé lisible, contrainte) est déjà exécuté en base.
//
// À appliquer sur la branche du lot R2 (lotR2-grille-aleatoire) : les lots R2 et R3 se testent ensemble en Preview.
//
//  - lib/gridOrderSettings.js          (nouveau) : saisie, valeur à enregistrer, bornes de la période, textes
//  - tests/gridOrderSettings.test.mjs  (nouveau) : controles automatiques
//  - components/AdminGridOrder.js      (nouveau) : le panneau d'administration
//  - sql/supabase_grid_order*.sql      (nouveaux, versionnement des 4 scripts déjà exécutés ; un fichier existant n'est pas écrasé)
//  - components/AdminSiteMedia.js : panneau ajouté au groupe « Vitrine & ambiance » (compteur 2 -> 3)
//  - lib/configLog.js             : libellés du journal des réglages (clé, champs, valeurs)
//  - pages/index.js               : la grille lit la ligne « grid_order » (au lieu du réglage par défaut du lot R2)
//
// Utilisation (depuis la racine du projet) :
//   node scripts/patch-lotR3b-admin-ordre-bijoux.mjs --dry-run   (controle les ancres, n'ecrit rien)
//   node scripts/patch-lotR3b-admin-ordre-bijoux.mjs             (applique)
//
// Le script s'arrete sans rien ecrire si une ancre est absente, en double ou inattendue.
// ============================================================
import fs from "node:fs";
import path from "node:path";

const DRY = process.argv.includes("--dry-run");
const ROOT = process.cwd();
const MARK = "ZENORIA_GRID_ORDER_V3";

function stop(msg) {
  console.error("\nARRET : " + msg + "\nRien n'a ete ecrit.");
  process.exit(1);
}
const count = (s, sub) => s.split(sub).length - 1;
const abs = (rel) => path.join(ROOT, ...rel.split("/"));

const NEW_FILES = [
  { rel: "lib/gridOrderSettings.js", content: "import {\n  DEFAULT_GRID_ORDER,\n  GRID_ORDER_MIN_DAYS,\n  GRID_ORDER_MAX_DAYS,\n  GRID_ORDER_ANCHOR_DAY,\n  GRID_ORDER_ROTATION_HOUR,\n  parseGridOrderSetting,\n  periodIndex,\n} from \"./gridOrder.js\";\nimport { addDaysToParisDay } from \"./dates.js\";\nimport { parisOffsetMinutes } from \"./parisTime.js\";\n\n// ============================================================\n// RÉGLAGE « ORDRE DES BIJOUX » (administration) — ZENORIA_GRID_ORDER_V3\n//\n// Enregistré dans la table site_settings, clé « grid_order » (voir sql/supabase_grid_order.sql) :\n//     { \"mode\": \"random\" | \"manual\", \"everyDays\": 1 à 30, \"shuffledAt\": \"\" }\n// Ce fichier contient tout ce que le panneau d'administration décide : lecture de la saisie, valeur à enregistrer, comparaison,\n// bornes de la période en cours, textes. Le panneau (components/AdminGridOrder.js) ne fait que l'afficher.\n// Le calcul de l'ordre lui-même est dans lib/gridOrder.js.\n// ============================================================\nexport const GRID_ORDER_KEY = \"grid_order\";\nconst TIME_ZONE = \"Europe/Paris\";\n\n// Saisie de la fréquence : « 7 », « 07 », « 7 jours » ; un nombre entier de 1 à 30\nexport function parseEveryDaysInput(text) {\n  const t = String(text === null || text === undefined ? \"\" : text)\n    .trim()\n    .toLowerCase()\n    .replace(/\\s+/g, \" \")\n    .replace(/ ?(jours?|j)$/, \"\");\n  if (!/^\\d{1,3}$/.test(t)) return { ok: false, value: null, error: \"Saisissez un nombre entier de jours, de \" + GRID_ORDER_MIN_DAYS + \" à \" + GRID_ORDER_MAX_DAYS + \".\" };\n  const n = Number(t);\n  if (n < GRID_ORDER_MIN_DAYS || n > GRID_ORDER_MAX_DAYS) {\n    return { ok: false, value: null, error: \"La fréquence doit être comprise entre \" + GRID_ORDER_MIN_DAYS + \" et \" + GRID_ORDER_MAX_DAYS + \" jours.\" };\n  }\n  return { ok: true, value: n, error: \"\" };\n}\n\n// Valeur à enregistrer : toujours complète et valide\nexport function buildGridOrderValue(s) {\n  const p = parseGridOrderSetting(s);\n  return { mode: p.mode, everyDays: p.everyDays, shuffledAt: p.shuffledAt };\n}\n\n// « Mélanger maintenant » : le réglage actuel, avec l'instant du mélange. null si l'instant est illisible.\nexport function shuffledValue(current, nowMs) {\n  const t = Number(nowMs);\n  if (!Number.isFinite(t)) return null;\n  let iso = \"\";\n  try {\n    iso = new Date(t).toISOString();\n  } catch (e) {\n    return null;\n  }\n  const p = parseGridOrderSetting(current);\n  return { mode: p.mode, everyDays: p.everyDays, shuffledAt: iso };\n}\n\n// Deux réglages sont-ils identiques pour le formulaire ? (la date du dernier mélange ne se saisit pas : elle est exclue)\nexport function sameGridOrderSetting(a, b) {\n  const x = parseGridOrderSetting(a);\n  const y = parseGridOrderSetting(b);\n  return x.mode === y.mode && x.everyDays === y.everyDays;\n}\n\n// Instant (millisecondes UTC) de « 3 h 00 à Paris » pour un jour « AAAA-MM-JJ », changements d'heure compris. NaN si le jour est illisible.\nexport function parisRotationMs(day) {\n  const m = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(String(day || \"\"));\n  if (!m) return NaN;\n  const local = Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]), GRID_ORDER_ROTATION_HOUR, 0, 0);\n  let t = local - parisOffsetMinutes(local) * 60000;\n  t = local - parisOffsetMinutes(t) * 60000; // deuxième passage : traverse un changement d'heure\n  return t;\n}\n\n// Période en cours : son numéro, son début et le prochain changement d'ordre (instants UTC en millisecondes)\nexport function periodBounds(nowMs, everyDays) {\n  const n = Number.isInteger(everyDays) && everyDays >= GRID_ORDER_MIN_DAYS ? everyDays : DEFAULT_GRID_ORDER.everyDays;\n  const period = periodIndex(nowMs, n);\n  return {\n    period,\n    startMs: parisRotationMs(addDaysToParisDay(GRID_ORDER_ANCHOR_DAY, period * n)),\n    nextMs: parisRotationMs(addDaysToParisDay(GRID_ORDER_ANCHOR_DAY, (period + 1) * n)),\n  };\n}\n\n// « lundi 16 novembre à 03:00 » (heure de Paris)\nexport function formatGridMoment(ms) {\n  if (!Number.isFinite(ms)) return \"—\";\n  return new Date(ms).toLocaleString(\"fr-FR\", { timeZone: TIME_ZONE, weekday: \"long\", day: \"numeric\", month: \"long\", hour: \"2-digit\", minute: \"2-digit\" });\n}\n\n// « 6 novembre 2026 à 14:32 » (heure de Paris) ; « jamais » si le réglage n'a jamais été mélangé à la main\nexport function formatShuffleMoment(iso) {\n  const t = typeof iso === \"string\" && iso !== \"\" ? Date.parse(iso) : NaN;\n  if (!Number.isFinite(t)) return \"jamais\";\n  return new Date(t).toLocaleString(\"fr-FR\", { timeZone: TIME_ZONE, day: \"numeric\", month: \"long\", year: \"numeric\", hour: \"2-digit\", minute: \"2-digit\" });\n}\n\n// Texte du réglage enregistré, pour l'administration\nexport function describeGridOrder(setting) {\n  const s = parseGridOrderSetting(setting);\n  if (s.mode === \"manual\") return \"manuel : les bijoux s'affichent dans l'ordre de la base\";\n  return \"aléatoire, nouvel ordre \" + (s.everyDays === 1 ? \"chaque jour\" : \"tous les \" + s.everyDays + \" jours\") + \" à 3 h (heure de Paris)\";\n}\n\n// Libellés du journal des changements (lot C5) : valeur lisible d'un champ du réglage.\n// Renvoie null pour tout ce qui n'est pas propre à ce réglage : le journal garde alors son affichage habituel.\n// (Les valeurs « random » et « manual » n'existent dans aucun autre réglage : « mode » des autres vaut auto, forced, off, once, loop, vanish, full, stars.)\nexport function formatGridOrderLogValue(field, v) {\n  if (field === \"mode\") {\n    if (v === \"random\") return \"aléatoire\";\n    if (v === \"manual\") return \"ordre de la base\";\n  }\n  if (field === \"everyDays\") {\n    const n = Number(v);\n    if (Number.isFinite(n)) return n + (n > 1 ? \" jours\" : \" jour\");\n  }\n  if (field === \"shuffledAt\") return formatShuffleMoment(v);\n  return null;\n}\n" },
  { rel: "tests/gridOrderSettings.test.mjs", content: "// Tests de lib/gridOrderSettings.js (lot R3) — se lancent avec : node tests/gridOrderSettings.test.mjs\nimport {\n  GRID_ORDER_KEY, parseEveryDaysInput, buildGridOrderValue, shuffledValue, sameGridOrderSetting,\n  parisRotationMs, periodBounds, formatGridMoment, formatShuffleMoment, describeGridOrder, formatGridOrderLogValue,\n} from \"../lib/gridOrderSettings.js\";\nimport { parseGridOrderSetting, periodIndex, parisHour, gridOrderIds } from \"../lib/gridOrder.js\";\nimport { parisOffsetMinutes } from \"../lib/parisTime.js\";\n\nlet ok = true;\nconst check = (c, m) => {\n  ok = ok && c;\n  console.log((c ? \"OK  \" : \"KO  \") + m);\n};\n\n// 1. Clé du réglage : celle que la base accepte\ncheck(GRID_ORDER_KEY === \"grid_order\" && /^[a-z][a-z0-9_]{0,39}$/.test(GRID_ORDER_KEY), \"clé « grid_order » conforme à la contrainte site_settings_key_format de la base\");\n\n// 2. Saisie de la fréquence\nconst good = { \"1\": 1, \" 7 \": 7, \"07\": 7, \"30\": 30, \"7 jours\": 7, \"1 jour\": 1, \"5j\": 5, \"12 J\": 12 };\ncheck(Object.entries(good).every(([t, n]) => { const r = parseEveryDaysInput(t); return r.ok && r.value === n && r.error === \"\"; }), \"saisies acceptées : 1, ' 7 ', 07, 30, '7 jours', '1 jour', '5j', '12 J'\");\nconst bad = [\"\", \"  \", \"0\", \"31\", \"-3\", \"2.5\", \"2,5\", \"abc\", \"7 semaines\", \"1000\", \"1e1\", null, undefined];\ncheck(bad.every((t) => { const r = parseEveryDaysInput(t); return !r.ok && r.value === null && r.error.length > 10; }), \"saisies refusées avec un message : vide, 0, 31, -3, 2.5, 2,5, texte, 1000, 1e1, null\");\ncheck(parseEveryDaysInput(\"0\").error.includes(\"entre 1 et 30\") && parseEveryDaysInput(\"abc\").error.includes(\"nombre entier\"), \"messages : hors bornes (« entre 1 et 30 ») et non numérique (« nombre entier »)\");\n\n// 3. Valeur à enregistrer : toujours acceptée par la contrainte de la base\n// (mode random|manual ; everyDays entier de 1 à 30 ; shuffledAt texte de 40 caractères au plus)\nconst dbOk = (v) => v && typeof v === \"object\" && [\"random\", \"manual\"].includes(v.mode) && Number.isInteger(v.everyDays) && v.everyDays >= 1 && v.everyDays <= 30 && typeof v.shuffledAt === \"string\" && v.shuffledAt.length <= 40 && Object.keys(v).length === 3;\ncheck([null, undefined, {}, { mode: \"x\", everyDays: 99, shuffledAt: 5 }, { mode: \"manual\", everyDays: \"7\" }, [1], \"x\"].every((s) => dbOk(buildGridOrderValue(s))), \"buildGridOrderValue : toute entrée donne une valeur que la contrainte de la base accepte\");\ncheck(JSON.stringify(buildGridOrderValue(null)) === JSON.stringify({ mode: \"random\", everyDays: 1, shuffledAt: \"\" }), \"réglage absent : { random, 1, '' } (la valeur par défaut du site)\");\ncheck(JSON.stringify(buildGridOrderValue({ mode: \"manual\", everyDays: 12, shuffledAt: \"2026-11-06T14:32:10.123Z\" })) === JSON.stringify({ mode: \"manual\", everyDays: 12, shuffledAt: \"2026-11-06T14:32:10.123Z\" }), \"valeur valide : conservée telle quelle\");\n\n// 4. « Mélanger maintenant »\nconst T = Date.UTC(2026, 10, 6, 13, 32, 10, 123);\nconst sv = shuffledValue({ mode: \"random\", everyDays: 7, shuffledAt: \"\" }, T);\ncheck(sv.shuffledAt === \"2026-11-06T13:32:10.123Z\" && sv.mode === \"random\" && sv.everyDays === 7 && dbOk(sv), \"mélange : mode et fréquence conservés, instant enregistré en ISO, valeur acceptée par la base\");\ncheck(shuffledValue(null, T).mode === \"random\" && shuffledValue(null, T).everyDays === 1, \"mélange sans réglage enregistré : valeurs par défaut + instant\");\ncheck(shuffledValue({ mode: \"manual\" }, T).mode === \"manual\", \"mélange : le mode manuel est conservé (le bouton sera désactivé, mais la fonction ne le change pas)\");\ncheck(shuffledValue({}, NaN) === null && shuffledValue({}, \"x\") === null && shuffledValue({}, 8.64e15 + 1) === null, \"instant illisible ou hors limites : null, aucun plantage\");\nconst base14 = () => Array.from({ length: 14 }, (_, i) => ({ id: i + 1 }));\nconst orderA = gridOrderIds(base14(), { nowMs: T, setting: { mode: \"random\", everyDays: 1, shuffledAt: \"\" } });\nconst orderB = gridOrderIds(base14(), { nowMs: T, setting: sv });\ncheck(orderA.join() !== orderB.join(), \"le mélange change réellement l'ordre vu par les visiteurs (avec la vraie logique de lib/gridOrder.js)\");\n\n// 5. Comparaison des réglages\ncheck(sameGridOrderSetting({ mode: \"random\", everyDays: 7, shuffledAt: \"\" }, { mode: \"random\", everyDays: 7, shuffledAt: \"2026-11-06T13:32:10.123Z\" }), \"même mode et même fréquence : identiques, quelle que soit la date de mélange\");\ncheck(!sameGridOrderSetting({ mode: \"random\", everyDays: 7 }, { mode: \"random\", everyDays: 8 }) && !sameGridOrderSetting({ mode: \"random\", everyDays: 7 }, { mode: \"manual\", everyDays: 7 }), \"fréquence ou mode différents : non identiques\");\ncheck(sameGridOrderSetting(null, { mode: \"random\", everyDays: 1 }), \"réglage absent = valeur par défaut\");\n\n// 6. Instant de « 3 h 00 à Paris » pour chaque jour de 2026 et 2027\nlet badRot = 0, count = 0;\nfor (let d = 0; d < 730; d++) {\n  const day = new Date(Date.UTC(2026, 0, 1 + d)).toISOString().slice(0, 10);\n  const t = parisRotationMs(day);\n  count++;\n  const local = new Date(t + parisOffsetMinutes(t) * 60000);\n  if (!Number.isFinite(t) || parisHour(t) !== 3 || local.getUTCMinutes() !== 0 || local.getUTCSeconds() !== 0 || local.toISOString().slice(0, 10) !== day) badRot++;\n}\ncheck(badRot === 0, \"parisRotationMs : les \" + count + \" jours de 2026-2027 donnent exactement 03:00:00 à Paris, le bon jour (changements d'heure compris)\");\ncheck(parisRotationMs(\"2026-03-29\") === Date.UTC(2026, 2, 29, 1, 0, 0) && parisRotationMs(\"2026-10-25\") === Date.UTC(2026, 9, 25, 2, 0, 0) && parisRotationMs(\"2026-07-01\") === Date.UTC(2026, 6, 1, 1, 0, 0) && parisRotationMs(\"2026-12-01\") === Date.UTC(2026, 11, 1, 2, 0, 0), \"03:00 Paris = 01:00 UTC en été (dont le 29/03), 02:00 UTC en hiver (dont le 25/10)\");\ncheck([\"\", \"x\", \"2026-13-40x\", null, undefined, \"2026/11/06\"].every((v) => Number.isNaN(parisRotationMs(v))), \"jour illisible : NaN, aucun plantage\");\n\n// 7. Bornes de la période, cohérentes avec periodIndex (celui qui décide de l'ordre).\n// Instants testés : toute l'année 2026 (un instant tous les 2 jours et 2 h environ) + un instant toutes les 20 minutes autour des deux changements d'heure\nconst sample = [];\nfor (let t = Date.UTC(2026, 0, 1); t < Date.UTC(2027, 0, 1); t += 50 * 3600000 + 777) sample.push(t);\nfor (const [m, d] of [[2, 28], [2, 29], [9, 24], [9, 25]]) for (let k = 0; k < 72; k++) sample.push(Date.UTC(2026, m, d) + k * 20 * 60000);\nfor (const n of [1, 2, 5, 7, 30]) {\n  let bad = 0;\n  for (const t of sample) {\n    const b = periodBounds(t, n);\n    const okBounds =\n      Number.isFinite(b.startMs) && Number.isFinite(b.nextMs) &&\n      b.startMs <= t && t < b.nextMs &&\n      periodIndex(b.startMs, n) === b.period && periodIndex(b.startMs - 1, n) === b.period - 1 &&\n      periodIndex(b.nextMs - 1, n) === b.period && periodIndex(b.nextMs, n) === b.period + 1 &&\n      b.nextMs - b.startMs >= n * 86400000 - 3600000 && b.nextMs - b.startMs <= n * 86400000 + 3600000;\n    if (!okBounds) bad++;\n  }\n  check(bad === 0, \"N = \" + n + \" : \" + sample.length + \" instants de 2026 (dont les 4 jours des changements d'heure), début et prochain changement toujours cohérents avec periodIndex, durée de \" + n + \" jour(s) à 1 h près\");\n}\ncheck(Number.isFinite(periodBounds(Date.UTC(2025, 5, 1), 7).startMs) && periodBounds(Date.UTC(2025, 5, 1), 7).period < 0, \"avant la date d'ancrage (2026) : période négative, bornes calculées quand même\");\ncheck(periodBounds(T, 0).period === periodBounds(T, 1).period && periodBounds(T, \"x\").period === periodBounds(T, 1).period, \"fréquence invalide : valeur par défaut (1 jour), aucun plantage\");\nconst b7 = periodBounds(Date.UTC(2026, 10, 12, 10, 0), 7);\ncheck(b7.startMs === Date.UTC(2026, 10, 9, 2, 0) && b7.nextMs === Date.UTC(2026, 10, 16, 2, 0), \"N = 7, jeudi 12/11/2026 : début lundi 9/11 à 03:00 Paris, prochain changement lundi 16/11 à 03:00 Paris\");\nconst b1 = periodBounds(Date.UTC(2026, 10, 9, 1, 59), 1);\ncheck(b1.startMs === Date.UTC(2026, 10, 8, 2, 0) && b1.nextMs === Date.UTC(2026, 10, 9, 2, 0), \"N = 1, lundi 9/11 à 02:59 Paris : encore la période commencée dimanche à 03:00, prochain changement lundi à 03:00\");\n\n// 8. Textes\ncheck(formatGridMoment(Date.UTC(2026, 10, 16, 2, 0)).includes(\"lundi 16 novembre\") && /03[:h]00/.test(formatGridMoment(Date.UTC(2026, 10, 16, 2, 0))), \"formatGridMoment : « lundi 16 novembre … 03:00 » (heure de Paris), obtenu : \" + formatGridMoment(Date.UTC(2026, 10, 16, 2, 0)));\ncheck(formatGridMoment(NaN) === \"—\" && formatGridMoment(undefined) === \"—\", \"formatGridMoment : valeur illisible -> tiret\");\ncheck(formatShuffleMoment(\"2026-11-06T13:32:10.123Z\").includes(\"6 novembre 2026\") && /14[:h]32/.test(formatShuffleMoment(\"2026-11-06T13:32:10.123Z\")), \"formatShuffleMoment : 13:32 UTC = 14:32 à Paris en novembre, obtenu : \" + formatShuffleMoment(\"2026-11-06T13:32:10.123Z\"));\ncheck([\"\", null, undefined, \"pas une date\", 5].every((v) => formatShuffleMoment(v) === \"jamais\"), \"formatShuffleMoment : vide ou illisible -> « jamais »\");\ncheck(describeGridOrder(null) === \"aléatoire, nouvel ordre chaque jour à 3 h (heure de Paris)\", \"description par défaut : \" + describeGridOrder(null));\ncheck(describeGridOrder({ mode: \"random\", everyDays: 7 }) === \"aléatoire, nouvel ordre tous les 7 jours à 3 h (heure de Paris)\", \"description N = 7\");\ncheck(describeGridOrder({ mode: \"manual\" }).startsWith(\"manuel :\"), \"description du mode manuel\");\n\n// 9. Journal des changements\ncheck(formatGridOrderLogValue(\"mode\", \"random\") === \"aléatoire\" && formatGridOrderLogValue(\"mode\", \"manual\") === \"ordre de la base\", \"journal : mode lisible\");\ncheck(formatGridOrderLogValue(\"everyDays\", 1) === \"1 jour\" && formatGridOrderLogValue(\"everyDays\", 7) === \"7 jours\" && formatGridOrderLogValue(\"everyDays\", \"30\") === \"30 jours\", \"journal : « 1 jour », « 7 jours »\");\ncheck(formatGridOrderLogValue(\"shuffledAt\", \"2026-11-06T13:32:10.123Z\").includes(\"6 novembre 2026\"), \"journal : date du mélange lisible\");\ncheck([\"auto\", \"forced\", \"off\", \"once\", \"loop\", \"vanish\", \"full\", \"stars\"].every((m) => formatGridOrderLogValue(\"mode\", m) === null) && formatGridOrderLogValue(\"speed\", \"slow\") === null, \"journal : les « mode » des AUTRES réglages (auto, forced, off, once, loop, vanish, full, stars) ne sont pas touchés (null = affichage habituel)\");\n\n// 10. Cohérence avec le parseur de R1\ncheck(JSON.stringify(parseGridOrderSetting(buildGridOrderValue({ mode: \"manual\", everyDays: 9 }))) === JSON.stringify({ mode: \"manual\", everyDays: 9, shuffledAt: \"\" }), \"écrire puis relire le réglage donne la même chose\");\n\nconsole.log(ok ? \"\\nTOUS LES CONTROLES OK\" : \"\\nECHEC\");\nprocess.exit(ok ? 0 : 1);\n" },
  { rel: "components/AdminGridOrder.js", content: "import React, { useCallback, useEffect, useMemo, useRef, useState } from \"react\";\nimport { Shuffle, RefreshCw } from \"lucide-react\";\nimport { supabase } from \"@/lib/supabase\";\nimport { SITE_SETTINGS_TABLE } from \"@/lib/siteSettings\";\nimport { parseGridOrderSetting } from \"@/lib/gridOrder\";\nimport {\n  GRID_ORDER_KEY,\n  parseEveryDaysInput,\n  buildGridOrderValue,\n  shuffledValue,\n  sameGridOrderSetting,\n  periodBounds,\n  formatGridMoment,\n  formatShuffleMoment,\n  describeGridOrder,\n} from \"@/lib/gridOrderSettings\";\n\n// ============================================================\n// CARTE « ORDRE DES BIJOUX » (onglet « Contenu du site » de /admin, groupe « Vitrine & ambiance ») — ZENORIA_GRID_ORDER_V3\n//\n// Trois informations, enregistrées dans la table « site_settings » (clé « grid_order ») :\n//  - le mode : « aléatoire » (nouvel ordre à chaque période) ou « manuel » (ordre de la base, comme avant) ;\n//  - la fréquence : un nouvel ordre tous les N jours (de 1 à 30), à 3 h du matin, heure de Paris ;\n//  - la date du dernier « Mélanger maintenant », qui change l'ordre pour tous sans attendre la prochaine période.\n//\n// La grille « Nos créations » de l'accueil lit ce réglage au chargement de la page (pages/index.js). Les calculs sont dans\n// lib/gridOrder.js (ordre) et lib/gridOrderSettings.js (saisie, aperçu, textes). Tant que rien n'est enregistré, le site utilise la\n// valeur par défaut : aléatoire, chaque jour. Voir sql/supabase_grid_order.sql.\n// ============================================================\n\nfunction friendlyError(err) {\n  const msg = (err && err.message) || String(err || \"\");\n  if (/site_settings_grid_order_valid|violates check constraint/i.test(msg)) {\n    return \"La valeur est refusée par la base. Vérifiez le mode et la fréquence (de 1 à 30 jours), puis réessayez.\";\n  }\n  if (/relation|does not exist|schema cache|could not find the table/i.test(msg)) {\n    return \"La table des réglages n'est pas installée. Exécutez le script supabase_site_settings.sql dans Supabase (SQL Editor).\";\n  }\n  if (/row-level security|permission denied|not authorized|unauthorized/i.test(msg)) {\n    return \"Enregistrement refusé : ce compte n'a pas les droits d'administration.\";\n  }\n  return msg;\n}\n\nconst MODES = [\n  { id: \"random\", label: \"Aléatoire\", sub: \"Un nouvel ordre à chaque période, le même pour tous les visiteurs.\" },\n  { id: \"manual\", label: \"Manuel\", sub: \"Les bijoux s'affichent dans l'ordre de la base, comme avant.\" },\n];\n\nexport default function AdminGridOrder() {\n  const [row, setRow] = useState(null); // ligne enregistrée (ou null : rien d'enregistré, donc valeur par défaut)\n  const [mode, setMode] = useState(\"random\");\n  const [text, setText] = useState(\"1\");\n  const [loading, setLoading] = useState(true);\n  const [loadError, setLoadError] = useState(\"\");\n  const [saving, setSaving] = useState(false);\n  const [error, setError] = useState(\"\");\n  const [toast, setToast] = useState(\"\");\n  const [nowMs, setNowMs] = useState(null); // renseigné après l'affichage : le rendu du serveur ne dépend jamais de l'heure\n  const radioRefs = useRef({});\n\n  const load = useCallback(async () => {\n    setLoading(true);\n    setLoadError(\"\");\n    try {\n      const res = await supabase.from(SITE_SETTINGS_TABLE).select(\"*\").eq(\"key\", GRID_ORDER_KEY).maybeSingle();\n      if (res.error) {\n        setLoadError(friendlyError(res.error));\n      } else {\n        const stored = res.data || null;\n        setRow(stored);\n        const parsed = parseGridOrderSetting(stored ? stored.value : null);\n        setMode(parsed.mode);\n        setText(String(parsed.everyDays));\n      }\n    } catch (err) {\n      setLoadError(friendlyError(err));\n    }\n    setLoading(false);\n  }, []);\n\n  useEffect(() => {\n    load();\n  }, [load]);\n\n  useEffect(() => {\n    setNowMs(Date.now());\n    const id = setInterval(() => setNowMs(Date.now()), 60000);\n    return () => clearInterval(id);\n  }, []);\n\n  useEffect(() => {\n    if (!toast) return undefined;\n    const t = setTimeout(() => setToast(\"\"), 4000);\n    return () => clearTimeout(t);\n  }, [toast]);\n\n  const saved = useMemo(() => parseGridOrderSetting(row ? row.value : null), [row]);\n  const input = useMemo(() => parseEveryDaysInput(text), [text]);\n  const draft = input.ok ? { mode, everyDays: input.value, shuffledAt: saved.shuffledAt } : null;\n  const modified = draft !== null && !sameGridOrderSetting(draft, saved); // la saisie diffère du réglage en vigueur\n  const dirty = draft !== null && (!row || modified); // « Enregistrer » est utile : modification, ou rien d'enregistré (il crée la ligne)\n  const disabled = loading || Boolean(loadError) || saving;\n  const manualDraft = mode === \"manual\";\n  const shown = draft || saved; // aperçu : si la saisie est invalide, on garde le dernier réglage valide\n\n  let shuffleWhy = \"\";\n  if (!input.ok) shuffleWhy = \"Corrigez la fréquence saisie avant de mélanger.\";\n  else if (modified) shuffleWhy = \"Enregistrez d'abord vos modifications pour pouvoir mélanger.\";\n  else if (saved.mode !== \"random\") shuffleWhy = \"Le mélange n'a d'effet qu'en mode aléatoire.\";\n\n  const write = async (value, okMessage) => {\n    setError(\"\");\n    setToast(\"\");\n    setSaving(true);\n    try {\n      const { error: err } = await supabase.from(SITE_SETTINGS_TABLE).upsert({ key: GRID_ORDER_KEY, value }, { onConflict: \"key\" });\n      if (err) throw err;\n      setToast(okMessage);\n      await load();\n    } catch (err) {\n      setError(\"Échec de l'enregistrement : \" + friendlyError(err));\n    }\n    setSaving(false);\n  };\n\n  const save = () => {\n    setError(\"\");\n    if (!draft) {\n      setError(input.error);\n      return;\n    }\n    write(buildGridOrderValue(draft), \"Réglage enregistré. Les visiteurs le voient au prochain chargement de la page.\");\n  };\n\n  const shuffle = () => {\n    if (disabled || shuffleWhy) return;\n    const value = shuffledValue(saved, Date.now());\n    if (!value) {\n      setError(\"Échec du mélange : l'heure de cet ordinateur est illisible.\");\n      return;\n    }\n    write(value, \"Nouvel ordre enregistré. Les visiteurs le voient au prochain chargement de la page.\");\n  };\n\n  const pickMode = (id) => {\n    if (disabled) return;\n    setMode(id);\n    setError(\"\");\n    setToast(\"\");\n  };\n\n  // Flèches du clavier dans le groupe de choix (comportement habituel d'un groupe de boutons radio)\n  const onRadioKey = (e) => {\n    if (![\"ArrowLeft\", \"ArrowRight\", \"ArrowUp\", \"ArrowDown\"].includes(e.key)) return;\n    e.preventDefault();\n    const next = mode === \"random\" ? \"manual\" : \"random\";\n    pickMode(next);\n    const el = radioRefs.current[next];\n    if (el) el.focus();\n  };\n\n  const bounds = nowMs !== null && shown.mode === \"random\" ? periodBounds(nowMs, shown.everyDays) : null;\n  const savedAt = row && row.updated_at ? formatShuffleMoment(row.updated_at) : null;\n\n  return (\n    <section data-testid=\"grid-order-panel\" className=\"mt-8 rounded-2xl bg-white border border-[#eee2e5] p-5\" aria-labelledby=\"grid-order-title\">\n      <div className=\"flex justify-between items-start gap-3\">\n        <div className=\"min-w-0\">\n          <h2 id=\"grid-order-title\" className=\"font-serif text-xl flex items-center gap-2\">\n            <Shuffle size={18} className=\"text-[#8f6075]\" /> Ordre des bijoux\n          </h2>\n          <p className=\"text-xs text-[#8b737e] mt-1 leading-4\">\n            L&apos;ordre dans lequel les créations s&apos;affichent dans la grille « Nos créations » de l&apos;accueil. En mode aléatoire, tous les visiteurs voient le même ordre, renouvelé à 3 h du matin (heure de Paris). Les bijoux commandables passent toujours avant les autres.\n          </p>\n        </div>\n        <button\n          type=\"button\"\n          onClick={load}\n          disabled={loading}\n          aria-label=\"Actualiser le réglage de l'ordre des bijoux\"\n          className=\"shrink-0 h-9 w-9 grid place-items-center rounded-full border border-[#d9c5cc] hover:bg-[#f5edf1] disabled:opacity-60\"\n        >\n          <RefreshCw size={14} className={loading ? \"animate-spin\" : \"\"} />\n        </button>\n      </div>\n\n      {toast && <div data-testid=\"grid-order-toast\" role=\"status\" className=\"mt-4 rounded-xl bg-emerald-50 text-emerald-700 px-4 py-3 text-sm\">{toast}</div>}\n      {loadError && <div data-testid=\"grid-order-load-error\" role=\"alert\" className=\"mt-4 rounded-xl bg-red-50 text-red-600 px-4 py-3 text-sm\">{loadError}</div>}\n      {error && <div data-testid=\"grid-order-error\" role=\"alert\" className=\"mt-4 rounded-xl bg-red-50 text-red-600 px-4 py-3 text-sm\">{error}</div>}\n\n      <div className=\"mt-5 text-xs text-[#8b737e]\" id=\"grid-order-mode-label\">\n        Ordre d&apos;affichage\n      </div>\n      <div role=\"radiogroup\" aria-labelledby=\"grid-order-mode-label\" className=\"mt-1.5 grid gap-2 sm:grid-cols-2\">\n        {MODES.map((m) => {\n          const on = mode === m.id;\n          return (\n            <button\n              key={m.id}\n              type=\"button\"\n              role=\"radio\"\n              aria-checked={on}\n              tabIndex={on ? 0 : -1}\n              ref={(el) => {\n                radioRefs.current[m.id] = el;\n              }}\n              disabled={disabled}\n              onClick={() => pickMode(m.id)}\n              onKeyDown={onRadioKey}\n              data-testid={\"grid-order-mode-\" + m.id}\n              className={`text-left rounded-xl border px-4 py-3 flex gap-3 items-start disabled:opacity-60 ${on ? \"border-[#8f6075] bg-[#faf6f8]\" : \"border-[#eee2e5] hover:bg-[#faf6f8]\"}`}\n            >\n              <span aria-hidden=\"true\" className={`mt-0.5 h-4 w-4 shrink-0 rounded-full border-2 grid place-items-center ${on ? \"border-[#8f6075]\" : \"border-[#d9c5cc]\"}`}>\n                {on && <span className=\"h-2 w-2 rounded-full bg-[#8f6075]\" />}\n              </span>\n              <span className=\"min-w-0\">\n                <span className=\"block text-sm font-medium\">{m.label}</span>\n                <span className=\"block text-[12px] text-[#756a70] leading-4 mt-0.5\">{m.sub}</span>\n              </span>\n            </button>\n          );\n        })}\n      </div>\n\n      <label className=\"block mt-5 text-sm\" htmlFor=\"grid-order-days\">\n        <span className=\"block text-xs text-[#8b737e]\">Nouvel ordre tous les</span>\n      </label>\n      <div className=\"mt-1 flex items-center gap-2\">\n        <input\n          id=\"grid-order-days\"\n          type=\"text\"\n          inputMode=\"numeric\"\n          autoComplete=\"off\"\n          value={text}\n          disabled={disabled || manualDraft}\n          onChange={(e) => {\n            setText(e.target.value);\n            setError(\"\");\n            setToast(\"\");\n          }}\n          aria-invalid={!input.ok}\n          aria-describedby=\"grid-order-days-help\"\n          data-testid=\"grid-order-days\"\n          className=\"w-24 rounded-xl border border-[#eadfe4] px-3 h-10 outline-none focus:border-[#8f6075] bg-white disabled:opacity-60\"\n        />\n        <span className=\"text-sm text-[#54434c]\">{input.ok && input.value > 1 ? \"jours\" : \"jour\"}</span>\n      </div>\n      <span id=\"grid-order-days-help\" data-testid=\"grid-order-days-help\" className={`block text-[11px] mt-1 leading-4 ${input.ok ? \"text-[#8b737e]\" : \"text-red-600\"}`}>\n        {input.ok ? \"Nombre entier de 1 à 30. Le nouvel ordre est appliqué à 3 h du matin, heure de Paris.\" : input.error}\n      </span>\n      {manualDraft && <span className=\"block text-[11px] text-[#8b737e] mt-1 leading-4\">Mode manuel : cette fréquence est conservée et reprendra effet au retour en mode aléatoire.</span>}\n\n      <div className=\"mt-5 rounded-xl bg-[#faf6f8] border border-[#eee2e5] px-4 py-3\" aria-live=\"polite\">\n        <div className=\"text-xs text-[#8b737e] mb-1.5\">{modified ? \"Aperçu avec les valeurs saisies (pas encore enregistrées)\" : \"Aperçu\"}</div>\n        <ul data-testid=\"grid-order-preview\" className=\"space-y-1 text-[13px] text-[#54434c] leading-5\">\n          {shown.mode === \"manual\" ? (\n            <li>Mode manuel : l&apos;ordre ne change jamais tout seul.</li>\n          ) : bounds ? (\n            <>\n              <li>\n                Période en cours depuis le <strong className=\"font-medium\">{formatGridMoment(bounds.startMs)}</strong>\n              </li>\n              <li>\n                Prochain changement d&apos;ordre : <strong className=\"font-medium\">{formatGridMoment(bounds.nextMs)}</strong>\n              </li>\n            </>\n          ) : null}\n          <li>\n            Dernier mélange manuel : <strong className=\"font-medium\">{formatShuffleMoment(saved.shuffledAt)}</strong>\n          </li>\n        </ul>\n      </div>\n\n      <div className=\"flex flex-wrap items-center gap-3 mt-5\">\n        <button\n          type=\"button\"\n          onClick={save}\n          disabled={disabled || !dirty}\n          data-testid=\"grid-order-save\"\n          className=\"rounded-full bg-[#8f6075] hover:bg-[#71485b] text-white px-6 h-10 text-sm disabled:opacity-50 disabled:hover:bg-[#8f6075]\"\n        >\n          {saving ? \"Enregistrement...\" : \"Enregistrer\"}\n        </button>\n        <button\n          type=\"button\"\n          onClick={shuffle}\n          disabled={disabled || Boolean(shuffleWhy)}\n          aria-describedby=\"grid-order-shuffle-hint\"\n          data-testid=\"grid-order-shuffle\"\n          className=\"rounded-full border border-[#8f6075] text-[#8f6075] hover:bg-[#f5edf1] px-5 h-10 text-sm inline-flex items-center gap-2 disabled:opacity-50 disabled:border-[#d9c5cc] disabled:text-[#8b737e] disabled:hover:bg-transparent\"\n        >\n          <Shuffle size={15} /> Mélanger maintenant\n        </button>\n        {!loadError && !loading && (\n          <p data-testid=\"grid-order-saved-text\" className=\"text-[11px] text-[#54434c] leading-4\">\n            Réglage actuel : <strong className=\"font-medium\">{describeGridOrder(saved)}</strong>\n            {savedAt && (\n              <span className=\"text-[#8b737e]\">\n                {\" \"}\n                · modifié le {savedAt}\n                {row && row.updated_by_email ? ` · ${row.updated_by_email}` : \"\"}\n              </span>\n            )}\n            {!row && <span className=\"text-[#8b737e]\"> · rien d&apos;enregistré : valeur par défaut</span>}\n          </p>\n        )}\n      </div>\n      <p id=\"grid-order-shuffle-hint\" data-testid=\"grid-order-shuffle-hint\" className=\"text-[11px] text-[#8b737e] mt-2 leading-4\">\n        {shuffleWhy || \"Change l'ordre pour tous les visiteurs dès leur prochain chargement de page, sans attendre 3 h du matin.\"}\n      </p>\n\n      <p className=\"text-[11px] text-[#8b737e] mt-3 leading-4\">\n        L&apos;ordre est calculé dans le navigateur de chaque visiteur, à partir de l&apos;heure de Paris. Un onglet déjà ouvert garde son ordre jusqu&apos;au prochain chargement de la page. Les changements de ce réglage sont inscrits dans le journal de Configuration.\n      </p>\n    </section>\n  );\n}\n" },
];
const SQL_FILES = [
  { rel: "sql/supabase_grid_order_checks.sql", content: "-- ============================================================\n-- ZENORIA : contrôles (LECTURE SEULE) avant et après supabase_grid_order.sql\n-- (réglage « Ordre des bijoux », clé « grid_order » de la table site_settings)\n--\n-- À exécuter dans Supabase > SQL Editor. Aucune de ces requêtes ne modifie quoi que ce soit.\n-- Exécutez-les AVANT supabase_grid_order.sql et envoyez-moi les résultats des requêtes 1, 3 et 4,\n-- puis relancez-les APRÈS pour confirmer le résultat.\n-- ============================================================\n\n-- 1) Politiques de la table site_settings. Avant : la lecture publique doit lister EXACTEMENT 8 clés\n--    (season_fx, ring_animation, site_texts, shipping, reviews, contact, payment_methods, cgv_text).\n--    Après : les mêmes 8 clés + grid_order, soit 9.\nselect policyname, cmd, qual\nfrom pg_policies\nwhere schemaname = 'public' and tablename = 'site_settings'\norder by policyname;\n\n-- 2) Contraintes de site_settings. Après : une ligne « site_settings_grid_order_valid » de plus.\nselect conname, pg_get_constraintdef(oid) as definition\nfrom pg_constraint\nwhere conrelid = 'public.site_settings'::regclass\norder by conname;\n\n-- 3) Déclencheurs de site_settings (le journal des réglages, lot C5, doit y figurer)\nselect tgname, pg_get_triggerdef(oid) as definition\nfrom pg_trigger\nwhere tgrelid = 'public.site_settings'::regclass and not tgisinternal;\n\n-- 4) Code de la fonction du déclencheur : je dois vérifier qu'elle journalise TOUTES les clés\n--    (et pas seulement une liste), pour que « Ordre des bijoux » apparaisse dans le journal\nselect p.proname, pg_get_functiondef(p.oid) as code\nfrom pg_proc p\njoin pg_trigger t on t.tgfoid = p.oid\nwhere t.tgrelid = 'public.site_settings'::regclass and not t.tgisinternal;\n\n-- 5) Une ligne « grid_order » existe-t-elle déjà ? Avant : aucune ligne (le site utilise alors la valeur par défaut :\n--    aléatoire, tous les jours).\nselect key, value, updated_at\nfrom public.site_settings\nwhere key = 'grid_order';\n\n-- 6) Colonnes de site_settings\nselect column_name, data_type, is_nullable\nfrom information_schema.columns\nwhere table_schema = 'public' and table_name = 'site_settings'\norder by ordinal_position;\n" },
  { rel: "sql/supabase_grid_order.sql", content: "-- ============================================================\n-- ZENORIA : réglage de l'ordre des bijoux de la grille d'accueil\n-- (onglet « Contenu du site » > groupe « Vitrine & ambiance » > carte « Ordre des bijoux »)\n--\n-- À exécuter UNE FOIS dans Supabase > SQL Editor, après avoir lu supabase_grid_order_checks.sql (lecture seule).\n-- Le script peut être relancé sans danger. Pour l'annuler : supabase_grid_order_rollback.sql.\n-- (Exécuté le 06/11/2026 ; politique relevée avant : 8 clés ; après : 9 ; test supabase_grid_order_test.sql : TEST_OK.)\n--\n-- Réglage enregistré dans site_settings, clé « grid_order », valeur JSON :\n--     { \"mode\": \"random\", \"everyDays\": 1, \"shuffledAt\": \"\" }\n--   mode       : « random » (aléatoire) ou « manual » (ordre de la base, comme avant)\n--   everyDays  : nombre entier de jours entre deux changements d'ordre, de 1 à 30 (l'ordre change à 3 h, heure de Paris)\n--   shuffledAt : instant (texte ISO) du dernier « Mélanger maintenant » ; vide : jamais mélangé à la main\n--\n-- Il fait deux choses, et rien d'autre :\n--  1. site_settings : lecture publique de la clé « grid_order », EN PLUS des 8 clés déjà ouvertes. Les visiteurs en ont besoin\n--     pour afficher la grille. ATTENTION : « alter policy ... using (...) » REMPLACE toute la liste. Le script reprend donc\n--     les 8 clés actuelles + la nouvelle. Avant de modifier quoi que ce soit, il VÉRIFIE que la politique en vigueur contient\n--     bien ces 8 clés et rien d'autre : sinon il s'arrête sans rien changer (une clé oubliée couperait par exemple les moyens\n--     de paiement du site).\n--  2. site_settings : contrôle de la valeur de « grid_order » (mode connu, nombre entier de jours de 1 à 30, date en texte),\n--     pour qu'une saisie abîmée ne casse jamais le site.\n--\n-- Les règles d'écriture ne changent pas : seuls les administrateurs (is_admin()) peuvent écrire.\n-- Aucune ligne n'est créée : tant que rien n'est enregistré, le site applique la valeur par défaut (aléatoire, tous les jours).\n-- Il ne touche à aucun autre réglage.\n-- ============================================================\n\nbegin;\n\n-- 0) Garde-fou : la politique actuelle est celle que ce script suppose\ndo $$\ndeclare\n  q text;\n  k text;\n  n integer;\n  attendu integer;\nbegin\n  select qual into q\n  from pg_policies\n  where schemaname = 'public' and tablename = 'site_settings' and policyname = 'site_settings_select_public';\n\n  if q is null then\n    raise exception 'ARRET : la politique site_settings_select_public est introuvable. Rien n''a ete modifie.';\n  end if;\n\n  foreach k in array array['season_fx', 'ring_animation', 'site_texts', 'shipping', 'reviews', 'contact', 'payment_methods', 'cgv_text'] loop\n    if position(quote_literal(k) in q) = 0 then\n      raise exception 'ARRET : la cle % ne figure plus dans la politique de lecture publique. Envoyez le resultat de la requete 1 de supabase_grid_order_checks.sql. Rien n''a ete modifie.', k;\n    end if;\n  end loop;\n\n  -- Nombre de clés listées : 8 avant ce script, 9 si le script a déjà été exécuté\n  n := (length(q) - length(replace(q, '::text', ''))) / length('::text');\n  attendu := case when position(quote_literal('grid_order') in q) > 0 then 9 else 8 end;\n  if n <> attendu then\n    raise exception 'ARRET : la politique liste % cles au lieu de % : une cle inconnue de ce script serait supprimee. Envoyez le resultat de la requete 1 de supabase_grid_order_checks.sql. Rien n''a ete modifie.', n, attendu;\n  end if;\nend\n$$;\n\n-- 1) Lecture publique des réglages : les 8 clés actuelles + grid_order\nalter policy site_settings_select_public on public.site_settings\n  using (key = any (array[\n    'season_fx'::text, 'ring_animation'::text, 'site_texts'::text, 'shipping'::text,\n    'reviews'::text, 'contact'::text, 'payment_methods'::text, 'cgv_text'::text,\n    'grid_order'::text\n  ]));\n\n-- 2) Contrôle de la valeur (le CASE garantit que le nombre de jours n'est lu que s'il est bien un nombre)\nalter table public.site_settings drop constraint if exists site_settings_grid_order_valid;\nalter table public.site_settings\n  add constraint site_settings_grid_order_valid\n  check (\n    key <> 'grid_order'\n    or (\n      coalesce(jsonb_typeof(value), ''::text) = 'object'\n      and coalesce(value ->> 'mode', ''::text) in ('random', 'manual')\n      and case\n            when coalesce(jsonb_typeof(value -> 'everyDays'), ''::text) = 'number'\n              then (value ->> 'everyDays')::numeric between 1 and 30\n                   and (value ->> 'everyDays')::numeric = trunc((value ->> 'everyDays')::numeric)\n            else false\n          end\n      and coalesce(jsonb_typeof(value -> 'shuffledAt'), 'string'::text) = 'string'\n      and length(coalesce(value ->> 'shuffledAt', ''::text)) <= 40\n    )\n  );\n\ncommit;\n\n-- Vérification (lecture seule) : la politique doit maintenant lister 9 clés, dont grid_order\nselect policyname, qual\nfrom pg_policies\nwhere schemaname = 'public' and tablename = 'site_settings' and policyname = 'site_settings_select_public';\n" },
  { rel: "sql/supabase_grid_order_test.sql", content: "-- ============================================================\n-- ZENORIA : test de la contrainte « grid_order » (À EXÉCUTER APRÈS supabase_grid_order.sql)\n--\n-- Le test essaie d'enregistrer des valeurs fausses (elles doivent être refusées) puis des valeurs justes (elles doivent\n-- être acceptées), le tout dans une transaction ANNULÉE à la fin : rien ne reste en base.\n-- Résultat attendu : une ligne « TEST_OK ».\n-- Si une erreur s'affiche, exécutez « rollback; » pour fermer la transaction, puis envoyez-moi le message d'erreur.\n-- ============================================================\n\nbegin;\n\ndo $$\ndeclare\n  v text;\n  refusees text[] := array[\n    '{\"mode\":\"random\",\"everyDays\":0,\"shuffledAt\":\"\"}',\n    '{\"mode\":\"random\",\"everyDays\":31,\"shuffledAt\":\"\"}',\n    '{\"mode\":\"random\",\"everyDays\":2.5,\"shuffledAt\":\"\"}',\n    '{\"mode\":\"random\",\"everyDays\":\"7\",\"shuffledAt\":\"\"}',\n    '{\"mode\":\"aleatoire\",\"everyDays\":1,\"shuffledAt\":\"\"}',\n    '{\"everyDays\":1,\"shuffledAt\":\"\"}',\n    '{\"mode\":\"random\",\"shuffledAt\":\"\"}',\n    '{\"mode\":\"random\",\"everyDays\":1,\"shuffledAt\":5}',\n    '{\"mode\":\"random\",\"everyDays\":1,\"shuffledAt\":null}',\n    '[1,2]',\n    '\"texte\"'\n  ];\n  acceptees text[] := array[\n    '{\"mode\":\"random\",\"everyDays\":1,\"shuffledAt\":\"\"}',\n    '{\"mode\":\"manual\",\"everyDays\":30,\"shuffledAt\":\"2026-11-06T14:32:10.123Z\"}',\n    '{\"mode\":\"random\",\"everyDays\":7}',\n    '{\"mode\":\"random\",\"everyDays\":1.0,\"shuffledAt\":\"\"}'\n  ];\nbegin\n  -- Valeurs fausses : chacune doit être refusée par la contrainte\n  foreach v in array refusees loop\n    begin\n      insert into public.site_settings (key, value) values ('grid_order', v::jsonb);\n      raise exception 'ACCEPTEE A TORT : %', v;\n    exception\n      when check_violation then\n        null; -- refus attendu\n    end;\n  end loop;\n\n  -- Valeurs justes : chacune doit être acceptée (puis retirée aussitôt)\n  foreach v in array acceptees loop\n    insert into public.site_settings (key, value) values ('grid_order', v::jsonb);\n    delete from public.site_settings where key = 'grid_order';\n  end loop;\n\n  -- Les autres réglages ne sont pas concernés par la contrainte\n  if (select count(*) from public.site_settings where key = 'grid_order') <> 0 then\n    raise exception 'Une ligne grid_order est restee en base.';\n  end if;\nend\n$$;\n\nrollback;\n\nselect 'TEST_OK : 11 valeurs refusees, 4 valeurs acceptees, rien enregistre' as resultat;\n" },
  { rel: "sql/supabase_grid_order_rollback.sql", content: "-- ============================================================\n-- ZENORIA : annule supabase_grid_order.sql\n-- À lancer seulement pour revenir en arrière. Le site retombe sur la valeur par défaut (aléatoire, tous les jours),\n-- ou sur l'ordre de la base si le code du lot R2 est lui aussi retiré.\n-- ============================================================\n\nbegin;\n\n-- Le réglage enregistré est retiré\ndelete from public.site_settings where key = 'grid_order';\n\nalter table public.site_settings drop constraint if exists site_settings_grid_order_valid;\n\n-- Lecture publique : on revient aux 8 clés précédentes (état relevé le 06/11/2026)\nalter policy site_settings_select_public on public.site_settings\n  using (key = any (array[\n    'season_fx'::text, 'ring_animation'::text, 'site_texts'::text, 'shipping'::text,\n    'reviews'::text, 'contact'::text, 'payment_methods'::text, 'cgv_text'::text\n  ]));\n\ncommit;\n\n-- Vérification (lecture seule) : la politique doit de nouveau lister 8 clés, sans grid_order\nselect policyname, qual\nfrom pg_policies\nwhere schemaname = 'public' and tablename = 'site_settings' and policyname = 'site_settings_select_public';\n" },
];

function read(rel) {
  if (!fs.existsSync(abs(rel))) stop(rel + " introuvable (lance le script depuis la racine du projet).");
  const raw = fs.readFileSync(abs(rel), "utf8");
  const crlf = (raw.match(/\r\n/g) || []).length;
  const lf = (raw.match(/\n/g) || []).length - crlf;
  if (crlf > 0 && lf > 0) stop(rel + " melange des fins de ligne CRLF et LF : je ne touche pas a un fichier dans cet etat.");
  return { rel, eol: crlf > 0 ? "\r\n" : "\n", text: raw.replace(/\r\n/g, "\n") };
}
function applyEdits(f, edits) {
  let t = f.text;
  for (const e of edits) {
    const n = count(t, e.from);
    if (n !== 1) stop(f.rel + " : ancre « " + e.label + " » trouvee " + n + " fois (attendu : 1). Le fichier a change depuis l'audit.");
    t = t.replace(e.from, () => e.to);
  }
  return t;
}
const toDisk = (f, t) => (f.eol === "\r\n" ? t.replace(/\n/g, "\r\n") : t);

