for (const f of NEW_FILES) if (fs.existsSync(abs(f.rel))) stop(f.rel + " existe deja : lot deja applique ?");
if (!fs.existsSync(abs("tests"))) stop("le dossier tests/ est introuvable.");

// ---------- pages/index.js ----------
